def pmp_check(addr: UInt, size: UInt, cmd: UInt, noTranslate: Bool, idx: Int): Unit = {
  pmp(idx).valid := resp(idx).valid || noTranslate
  pmp(idx).bits.addr := addr
  pmp(idx).bits.size := size
  pmp(idx).bits.cmd := cmd
}
